import{_ as e,o as a,c as n,a5 as d}from"./chunks/framework.C1a7WKBV.js";const g=JSON.parse('{"title":"Agent 工程","description":"深入学习 Agent 架构、工具协议、上下文与记忆、评测观测和多 Agent 协作。","frontmatter":{"title":"Agent 工程","description":"深入学习 Agent 架构、工具协议、上下文与记忆、评测观测和多 Agent 协作。"},"headers":[],"relativePath":"agents/index.md","filePath":"agents/index.md","lastUpdated":1788838685000}'),r={name:"agents/index.md"};function s(o,t,i,l,h,c){return a(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="agent-工程" tabindex="-1">Agent 工程 <a class="header-anchor" href="#agent-工程" aria-label="Permalink to &quot;Agent 工程&quot;">​</a></h1><p>Agent 不是“带人格的聊天机器人”，而是一个<strong>让模型在受控状态机中选择动作、观察结果并继续执行的系统</strong>。真正决定可靠性的，往往不是提示词有多长，而是状态如何保存、工具如何设计、权限如何约束、失败如何恢复、轨迹如何评测。</p><h2 id="_1-专题地图" tabindex="-1">1. 专题地图 <a class="header-anchor" href="#_1-专题地图" aria-label="Permalink to &quot;1. 专题地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文章</th><th>核心问题</th><th>完成后能做什么</th></tr></thead><tbody><tr><td>《<a href="/ai-handbook/agents/architecture">Agent 系统架构</a>》</td><td>循环、状态机、终止与恢复</td><td>设计一个可控的单 Agent 运行时</td></tr><tr><td>《<a href="/ai-handbook/agents/tool-design-and-mcp">工具设计与 MCP</a>》</td><td>Schema、幂等、权限、协议边界</td><td>把业务能力变成模型容易正确调用的工具</td></tr><tr><td>《<a href="/ai-handbook/agents/context-and-memory">上下文工程与记忆</a>》</td><td>工作集、压缩、短期与长期记忆</td><td>在有限窗口里保留真正有用的信息</td></tr><tr><td>《<a href="/ai-handbook/agents/evaluation-and-observability">Agent 评测与可观测性</a>》</td><td>轨迹、成功率、故障分类</td><td>判断 Agent 为什么成功或失败</td></tr><tr><td>《<a href="/ai-handbook/agents/multi-agent-systems">多 Agent 系统</a>》</td><td>并行、委派、仲裁、共享状态</td><td>判断何时拆分角色，以及如何控制协作成本</td></tr></tbody></table><h2 id="_2-一条核心设计原则" tabindex="-1">2. 一条核心设计原则 <a class="header-anchor" href="#_2-一条核心设计原则" aria-label="Permalink to &quot;2. 一条核心设计原则&quot;">​</a></h2><p>把完整任务画成状态图。如果大多数下一步都能由代码提前确定，就使用普通工作流；只把需要语义判断的节点交给模型。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>固定工作流：A → B → C → D</span></span>
<span class="line"><span>Agent：A → 模型根据观察选择 B / C / 请求补充 → 再规划</span></span></code></pre></div><p>Agent 的价值来自<strong>适应中间结果</strong>，代价是路径不确定、调用次数增加、复现变难。好的架构不是让模型决定一切，而是把自主性放在最有收益的窄区域。</p><h2 id="_3-学习前置" tabindex="-1">3. 学习前置 <a class="header-anchor" href="#_3-学习前置" aria-label="Permalink to &quot;3. 学习前置&quot;">​</a></h2><p>建议先读《<a href="/ai-handbook/concepts/model-api-client">模型、服务、API 与客户端</a>》和《<a href="/ai-handbook/development/production-architecture">生产级 AI 应用架构</a>》。如果只想使用现成编程 Agent，可从《<a href="/ai-handbook/tutorials/first-project">第一个 AI 编程项目</a>》开始；本专题面向想理解或构建 Agent 系统的开发者。</p>`,10)])])}const _=e(r,[["render",s]]);export{g as __pageData,_ as default};
